for (const recipe of recipes) {
  if (recipeImages[recipe.id]) {
    recipe.image = recipeImages[recipe.id];
  }
}

export function getRecipeById(id: string): Recipe | undefined {
  return recipes.find((r) => r.id === id);
}

export function getRecipesByCategory(category: RecipeCategory): Recipe[] {
  return recipes.filter((r) => r.category === category);
}

export function getRecipesByBook(bookId: string): Recipe[] {
  return recipes.filter((r) => r.bookId === bookId);
}

export function getCategories(): { id: RecipeCategory; name: string; description: string; count: number }[] {
  const categoryInfo: Record<RecipeCategory, { name: string; description: string }> = {
    tutorial: { name: 'Tutorial', description: 'Start here — your first sourdough loaf' },
    'free-form-loaves': { name: 'Free-Form Loaves', description: 'Classic hearth-style sourdough breads' },
    'pan-loaves': { name: 'Pan Loaves', description: 'Sandwich breads, brioche, and more' },
    'pizzas-flatbreads': { name: 'Pizzas & Flatbreads', description: 'Pizza dough, focaccia, naan, and flatbreads' },
    'buns-rolls-more': { name: 'Buns, Rolls & More', description: 'Rolls, bagels, biscuits, and beyond' },
    sweets: { name: 'Sweets', description: 'Cinnamon rolls, doughnuts, pancakes, and treats' },
  };

  return (Object.keys(categoryInfo) as RecipeCategory[]).map((id) => ({
    id,
    ...categoryInfo[id],
    count: recipes.filter((r) => r.category === id).length,
  }));
}
